      section('Medical information', f.medical.value); section('Notes', f.notes.value); pg.drawText(`Updated ${new Date().toISOString().slice(0, 10)} · keep it on the fridge or next to the phone`, { x: M, y: M - 10, size: 9, font, color: PL.rgb(0.5, 0.52, 0.58) });
