    const go = btn('Start sprint', start, 'primary'), stopB = btn('Finish now', finish, 'secondary', { disabled: true }); mins.addEventListener('input', () => { if (!running) clock.textContent = fmt(mins.value * 60000); });
    ui.append(h('div', { class: 'ut-options' }, field('Sprint length (minutes)', mins), field('Word goal (0 = none)', goal)), h('div', { class: 'ut-actions' }, clock, go, stopB), bar, info, ta, res, h('div', { class: 'ut-actions' }, btn(t('copy'), () => copyText(ta.value), 'secondary'), btn('Download .txt', () => download('sprint.txt', ta.value), 'secondary')), h('p', { class: 'pt-hint' }, 'Write first, edit later. The text is only kept in this page: copy or download it before closing. Nothing is uploaded.')); clock.textContent = fmt(mins.value * 60000);
